export default async function(app){const reactiveUtils=await app.import('esri/core/reactiveUtils');const c=app.config;let disposed=false;const records=[];const previous=new Map();app.onCleanup(()=>{disposed=true;watch?.remove();for(const [layer,props]of previous){if(!layer.destroyed){layer.renderer=props.renderer;if(layer.trackInfo){layer.trackInfo.latestObservations.renderer=props.latest;layer.trackInfo.latestObservations.labelingInfo=props.labels;layer.trackInfo.previousObservations.renderer=props.dots;layer.trackInfo.trackLines.renderer=props.lines;}}}for(const [l,id,p]of records){if(!l.destroyed)l.setPaintProperties(id,p);}});let watch;
const icon=(plow,color)=>({type:'picture-marker',width:34,height:34,url:'data:image/svg+xml;base64,'+btoa(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64"><circle cx="32" cy="32" r="29" fill="#3A3128" stroke="${color}" stroke-width="2"/><g stroke="#1E2227" stroke-width="2"><path d="${plow?'M10 24H32V40H10ZM32 28H43L49 35V40H32Z':'M10 32H27V24H39L48 33V40H10Z'}" fill="${color}"/><path d="M33 28H39L44 33H33Z" fill="#F8F2E7"/>${plow?'<path d="M49 36L57 32V45L49 42Z" fill="'+color+'"/>':''}<circle cx="20" cy="42" r="5" fill="#1E2227" stroke="#F1E7D6"/><circle cx="41" cy="42" r="5" fill="#1E2227" stroke="#F1E7D6"/></g></svg>`)});
const makeRenderer=(kind)=>({type:'unique-value',field:'vehicletype',defaultLabel:'Other vehicle',defaultSymbol:kind==='icon'?icon(false,c.grey):kind==='dot'?{type:'simple-marker',size:4,color:c.grey,outline:{color:'#1E2227',width:0.5}}:{type:'simple-line',color:c.grey,width:1.5},uniqueValueInfos:[['Snow Plow',c.snow],['Pickup',c.pickup]].map(([value,color])=>({value,label:value,symbol:kind==='icon'?icon(value==='Snow Plow',color):kind==='dot'?{type:'simple-marker',size:4,color,outline:{color:'#1E2227',width:0.5}}:{type:'simple-line',color,width:1.5}}))});
function styleStream(){const l=app.map.allLayers.find(l=>l.id===c.layerId);if(!l?.trackInfo||previous.has(l)||disposed)return;previous.set(l,{renderer:l.renderer,latest:l.trackInfo.latestObservations.renderer,labels:l.trackInfo.latestObservations.labelingInfo,dots:l.trackInfo.previousObservations.renderer,lines:l.trackInfo.trackLines.renderer});l.renderer=makeRenderer('icon');l.trackInfo.latestObservations.renderer=makeRenderer('icon');l.trackInfo.latestObservations.labelingInfo=[{labelExpressionInfo:{expression:'$feature.vehiclename'},labelPlacement:'above-center',symbol:{type:'text',color:'#F1E7D6',haloColor:'#1E2227',haloSize:1.5,font:{size:9}}}];l.trackInfo.previousObservations.renderer=makeRenderer('dot');l.trackInfo.trackLines.renderer=makeRenderer('line');}
watch=reactiveUtils.watch(()=>{const l=app.map.allLayers.find(l=>l.id===c.layerId);return [l,l?.trackInfo];},styleStream);styleStream();let changed=0;for(const l of [...app.map.basemap.baseLayers,...app.map.basemap.referenceLayers]){if(l.type!=='vector-tile')continue;await l.load();if(disposed)return;const style=l.currentStyleInfo?.style;for(const part of style?.layers??[]){const old=l.getPaintProperties(part.id);const p={...old};if(part.type==='background')p['background-color']='#1E2227';else if(part.type==='fill'){p['fill-color']=/water|ocean/i.test(part.id)?'#1E2227':'#282C30';if(p['fill-outline-color'])p['fill-outline-color']='#35383B';}else if(part.type==='line'){p['line-color']='#454744';}else if(part.type==='symbol'&&part.layout?.['text-field']){p['text-color']='#F1E7D6';p['text-halo-color']='#1E2227';p['text-halo-width']=1;}else continue;records.push([l,part.id,old]);l.setPaintProperties(part.id,p);changed++;}}
app.actions.register('inspect-maritime-map',()=>{const l=app.map.allLayers.find(l=>l.id===c.layerId);return {basemapStyleParts:changed,categories:l?.renderer?.uniqueValueInfos?.map(v=>({value:v.value,color:v.value==='Snow Plow'?c.snow:c.pickup})),previousObservationColors:l?.trackInfo?.previousObservations.renderer?.uniqueValueInfos?.map(v=>({value:v.value,color:v.symbol.color.toHex()})),labels:l?.trackInfo?.latestObservations.labelingInfo?.[0]?.symbol.color.toHex()};});}